func (s *Store) UpdateWorkflow(owner string, cmd WorkflowCommand) (State, error) {
	var denied error
	state, err := s.update(owner, func(state *State) error {
		w := &state.Task.Workflow
		if state.Task.ID != cmd.TaskID || w.Version != cmd.Version {
			return ErrConflict
		}
		before := w.Stage
		next, e := PreviewWorkflow(*w, cmd)
		if e != nil {
			denied = e
			appendWorkflowEvent(w, cmd, before, e)
			return nil
		}
		*w = next
		w.Version++
		appendWorkflowEvent(w, cmd, before, nil)
		return nil
	})
	if err != nil {
		return state, err
	}
	return state, denied
}

// RecordWorkflowRejection records a semantic rejection without changing progress.
func (s *Store) RecordWorkflowRejection(owner string, cmd WorkflowCommand, reason error) error {
	_, err := s.update(owner, func(state *State) error {
		if state.Task.ID != cmd.TaskID || state.Task.Workflow.Version != cmd.Version {
			return ErrConflict
		}
		appendWorkflowEvent(&state.Task.Workflow, cmd, state.Task.Workflow.Stage, reason)
		return nil
	})
	return err
}
func truncateTurn(value string, limit int) string {
	chars := []rune(value)
	if len(chars) > limit {
		return string(chars[:limit]) + "\n[Сокращено; полный текст в истории диалога]"
	}
	return value
}

// PreserveApprovedArtifacts keeps model paraphrases from replacing immutable
// plan/goal or the artifact under review. Replanning is an explicit exception.
func PreserveApprovedArtifacts(w Workflow, p Progress) Progress {
	if w.Stage != "planning" && p.Stage != "plannin

ps model paraphrases from replacing immutable
// plan/goal or the artifact under review. Replanning is an explicit exception.
func PreserveApprovedArtifacts(w Workflow, p Progress) Progress {
	if w.Stage != "planning" && p.Stage != "planning" {
		p.Plan = w.Plan
		p.Goal = w.Goal
	}
	if w.Stage == "validation" {
		p.Result = w.Result
	}
	return p
}

// RecordTaskTurn retains a recovery checkpoint even if extraction fails. The
// proposal is optional and remains separate from the confirmed checkpoint.
func (s *Store) RecordTaskTurn(owner, taskID string, version int, user, answer string, proposal *TaskProposal) (State, error) {
	return s.update(owner, func(state *State) error {
		w := &state.Task.Workflow
		if state.Task.ID != taskID || w.Version != version || w.Paused || w.Stage == "done" {
			return ErrConflict
		}
		if proposal != nil {
			copy := *proposal
			copy.Progress = PreserveApprovedArtifacts(*w, copy.Progress)
			proposal = &copy
			if err := ValidateProgress(w.Stage, proposal.Progress); err != nil {
				return err
			}
			if strings.TrimSpace(proposal.Reason) == "" || utf8.RuneCountInString(proposal.Reason) > 1000 {
				return ErrInvalid
			}
		}
		w.LastTurn = &TaskTurn{User: truncateTurn(user, 6000), Assistant: truncateTurn(answer, 12000)}
		w.Proposal = proposal
		w.Version++
		return nil
	})
}

## Безопасность

- сервер по умолчанию слушает только `127.0.0.1`;
- Docker публикует порт только на loopback-интерфейсе;
- API-ключ остаётся в окружении Go-процесса;
- POST-маршруты требуют служебный заголовок и проверяют `Origin`;
- включены CSP, запрет iframe, `nosniff` и строгая cookie;
- размер JSON-запроса ограничен 1 МиБ;
- файл истории создаётся с правами `0600` и не попадает в Git;
- Markdown-рендерер создаёт только разрешённые DOM-элементы, а содержимое вставляет как текст; сырой HTML не исполняется, ссылки фильтруются по протоколу.

`store: true` необходим текущей схеме с `previous_response_id`. Это означает,
что ответы могут храниться на стороне OpenAI согласно политике Responses API,
даже если локальный сервер не пишет транскрипт на диск.

## Ограничения

Модель памяти описана в [MEMORY.md](MEMORY.md). `agent.WithMemory` подключает
отдельное хранилище, извлечение предложений после ответа и включение только
подтверждённых записей в следующий запрос. В приложении опция включена при
запуске. С ней все стратегии, включая Branching, воспроизводят активную историю
явно, чтобы исправленная память не оставалась в цепочке `previous_response_id`.
Frontend `memory.js` управляет памятью и операциями задачи. `app.js` переключает
вкладки «Чат» и «Задачи» без потери черновика сообщения. Создание задачи и
редактирование рабочей памяти вынесены на вкладку «Задачи».

- ответы приходят целиком, без token streaming;
- JSON-хранилище рассчитано на один процесс приложения и не использует
  межпроцессные блокировки;
- история хранится локально без шифрования диска;
- Markdown-рендерер намеренно не поддерживает сырой HTML и загрузку внешних изображений;
- нет аутентификации пользователей: приложение рассчитано на локальный запуск;
- автоматические повторы для временных ошибок API пока не реализованы.

## Возможности

- адаптивный интерфейс для компьютера и телефона;
- отдельный агент для каждого браузерного диалога;
- многострочный ввод: `Enter` отправляет, `Shift+Enter` добавляет строку;
- отдельный контекст для каждого браузера через защищённую cookie;
- история сообщений в локальном JSON-файле;
- автоматическое восстановление контекста и переписки после перезапуска приложения;
- безопасное отображение Markdown: заголовки, списки, таблицы, цитаты, ссылки и блоки кода;
- выбор модели перед отправкой сообщения;
- перенос всей сохранённой истории в контекст новой модели при переключении;
- время ответа, расход токенов и ориентировочная стоимость под каждым ответом;
- точный предварительный подсчёт токенов текущего запроса и активной истории;
- заполнение контекстного окна и накопленные токены/стоимость всего диалога в левой панели;
- неблокирующее предупреждение при превышении входного лимита модели;
- режим «Без стратегии» с полной историей и три стратегии контекста: Sliding Window, Sticky Facts и Branching;
- отдельная память важных фактов и независимые ветки от общего checkpoint;
- профили пользователя с настройками языка, стиля, подробности, формата и ограничений;
- отдельные задачи и память для каждого профиля, снимок настроек под каждым ответом;
- три отдельных слоя памяти: переписка, данные задачи и долговременный профиль;
- просмотр памяти по вкладкам: диалог, рабочая, долговременная, предложения и история решений;
- поиск по записям, карточки с источником и редактирование по нажатию;
- предложения памяти с подтверждением, выбором слоя, редактированием и отклонением;
- кнопки под каждым сообщением для прямого сохранения в рабочую или долговременную память;
- сохранённые задачи с переключением между их диалогами, рабочей памятью и стратегиями контекста;
- новый

ыбором слоя, редактированием и отклонением;
- кнопки под каждым сообщением для прямого сохранения в рабочую или долговременную память;
- сохранённые задачи с переключением между их диалогами, рабочей памятью и стратегиями контекста;
- новый диалог без перезапуска сервера;
- встроенные CSS и JavaScript без внешних frontend-зависимостей.

## Требования

- Go 1.25 или новее;
- OpenAI API key с доступом к выбранной модели;
- настроенный биллинг OpenAI API, если он требуется для аккаунта.

Подписка ChatGPT и биллинг OpenAI API — отдельные продукты.

## HTTP-маршруты

- `GET /` — веб-интерфейс;
- `POST /api/chat` — отправка сообщения;
- `GET /api/history` — восстановление сообщений текущего браузерного диалога;
- `POST /api/reset` — сброс контекста текущего браузера;
- `GET /api/memory` — память активной задачи, общий профиль и список задач;
- `POST /api/tasks/new` — создать задачу (`taskId` текущей задачи, `name` новой);
- `GET /api/profiles` — профили, примеры настроек и состояние активного профиля;
- `POST /api/profiles/new` — создать профиль;
- `POST /api/profiles/edit` — обновить профиль;
- `POST /api/profiles/switch` — переключить профиль и восстановить его данные;
- `POST /api/tasks/switch` — открыть сохранённую задачу (`taskId` текущей задачи, `id` выбранной);
- `POST /api/branches/create` — checkpoint и две независимые ветки;
- `POST /api/branches/switch` — переключение активной ветки;
- `GET /api/status` — модель по умолчанию и доступный список моделей;
- `GET /healthz` — проверка готовности сервера.

`POST /api/chat` принимает обязательное поле `message`, выбранную модель `model`, три необязательных
строковых поля (`responseFormat`, `lengthLimit`, `completionCondition`) и
необязательное числовое поле `temperature` от 0 до 2. Непустые строковые
значения добавляются к обязательным требованиям текущего ответа, а температура
передаётся отдельным параметром Responses API. Если `message` пустое, запрос к
модели не выполняется независимо от дополнительных полей.

## Пауза и восстановление

На planning, execution и validation отдельно проверены:
- отключение отправки и переходов в браузере;
- отказ HTTP 409 на сообщение и сохранение состояния во время паузы;
- сохранение паузы после перезагрузки страницы;
- переключение на другую задачу и обратно с сохранением шага, плана, результата и версий;
- снятие паузы без перехода этапа и без автоматической генерации ответа.

Реальные прогоны дополнительно пересоздают хранилище и агента, затем отправляют «Продолжи».
Во всех шести продолжениях модель использовала сохранённые требования: дала план в planning,
реализацию в execution и замечания к сохранённому результату в validation.

## Дополнительная проверка формы с табами

Во время основного прогона появились изменения `task-state.js` и `app.css` из
параллельной работы. Они не изменялись и не откатывались в рамках этой проверки.
В отдельной сборке дополнительно проверены:

- открытие скрытого таба с незаполненным обязательным планом или результатом;
- сохранение полей при переключении табов и отправка формы из другого таба;
- утверждённый план доступен только для чтения;
- навигация стрелками клавиатуры;
- успешные переходы planning → execution → validation;
- блокировка завершения без подтверждения проверки;
- отсутствие ошибок JavaScript.

Все эти проверки прошли. SHA-256 проверенных файлов сохранены в отчёте JSON.
После сборки появилась ещё одна параллельная правка — автоподстановка плана из
предложения, остающегося в planning. Эта дополнительная функция в текущий прогон
не вошла; она не входила в исходный перечень сценариев.

## Проверки

Автоматические тесты покрывают:

- паузу, перезапуск, переключение задач и продолжение на каждом рабочем этапе;
- обратный переход к исправлениям и терминальность `done`;
- недопустимые переходы, отсутствие результата/проверки и устаревшие версии;
- предложение без автоматического применения, подтверждение и отклонение;
- миграцию активной и сохранённых задач без состояния;
- продолжение после очистки чата с текущим шагом и выполненной работой в контексте;
- отсутствие вызовов модели на паузе и после завершения;
- сохранение последнего обмена при сбое извлечения;
- изоляцию HTTP-сессий/профилей и отклонение запросов с чужого сайта.

`go test -race ./...` и `go vet ./...` проходят. Браузерная проверка использует
отдельный сервер с имитацией модели и отдельные данные: получение предложения,
подтверждение, пауза, перезагрузка страницы и продолжение кнопкой.
Проверки ответов здесь детерминированные: подтверждают передачу состояния в модель,
но не гарантируют поведение каждой реальной LLM.

Историческая проверка до введения обязательных подтверждений на `gpt-5.3-codex` сохранена в [TASK_STATE_EVAL.json](TASK_STATE_EVAL.json).
Во всех трёх случаях задача была приостановлена, агент пересоздан, запрос на паузе
отклонён, затем после снятия паузы отправлено одно и то же «Продолжи» без переписки:

| Сохранённый этап | Ответ модели | Предложенный следующий этап |
| --- | --- | --- |
| planning | План валидатора, ожидание подтверждения перед кодом | execution |
| execution | Реализация Go-функции по сохранённым правилам | validation |
| validation | Найден пропуск проверки символов, предложено исправление без выдачи нового кода | execution |

// Package agent encapsulates the complete request/response flow of the coding
// assistant independently from HTTP delivery and the OpenAI transport.
package agent

// LLM is the transport boundary used by Agent to call a language model.
type LLM interface {
	Complete(ctx context.Context, request CompletionRequest) (CompletionResponse, error)
}

// TokenCounter returns exact input-token counts before an LLM request.
type TokenCounter interface {
	CountTokens(ctx context.Context, request CompletionRequest) (TokenCounts, error)
}

// ContextMessage is one prior conversational message replayed when an API
// response chain cannot be continued, for example after switching models.
type ContextMessage struct {
	Role    string
	Content string
}

// CompletionResponse is the transport-neutral result returned by an LLM.
type CompletionResponse struct {
	ToolCalls  []ToolCall
	ToolRuns   []ToolRun
	ResponseID string
	Output     string
	Model      string
	Usage      Usage
}

// Usage contains token counts reported by the LLM API.
type Usage struct {
	InputTokens       int
	CachedInputTokens int
	CacheWriteTokens  int
	OutputTokens      int
	ReasoningTokens   int
	TotalTokens       int
}

// Response is the final result prepared by the agent for the interface layer.
type Response struct {
	Text         string
	Model        string
	Usage        Usage
	Duration     time.Duration
	CostUSD      *float64
	TokenMetrics TokenMetrics
}

// History is the persistence boundary owned by Agent.
type History interface {
	Load(conversationID string) (ConversationState, error)
	Save(conversationID string, state ConversationState) error
	Delete(conversationID string) error
}

// New creates an independent agent conversation.
func New(llm LLM, defaultModel string, options ...Option) *Agent {
	defaultStrategy := normalizeStrategyConfig(StrategyConfig{Type: StrategySlidingWindow})
	a := &Agent{
		llm:             llm,
		defaultModel:    strings.TrimSpace(defaultModel),
		compression:     normalizeCompressionConfig(CompressionConfig{}),
		strategy:        defaultStrategy,
		defaultStrategy: defaultStrategy,
		facts:           make(map[string]string),
		branches:        make(map[string]BranchState),
	}
	if counter, ok := llm.(TokenCounter); ok {
		a.tokenCounter = counter
	}
	for _, option := range options {
		if option != nil {
			option(a)
		}
	}
	return a
}

// NewPersistent creates an agent and restores its conversation when it exists.
func NewPersistent(llm LLM, defaultModel, conversationID string, history History, options ...Option) (*Agent, error) {
	conversationID = strings.TrimSpace(conversationID)
	if conversationID == "" && history != nil {
		return nil, errors.New("conversation ID is required for persistent history")
	}

	a := New(llm, defaultModel, options...)
	a.history = history
	a.conversationID = conversationID
	a.browserID = conversationID
	if a.profileStore != nil {
		profiles, err := a.profileStore.Get(a.browserID)
		if err != nil {
			return nil, err
		}
		p := profiles.Active()
		a.activeProfile = &p
		a.conversationID = p.ID
	}
	if a.memoryStore != nil {
		layers, err := a.memoryStore.Get(a.conversationID)
		if err != nil {
			return nil, err
		}
		a.taskID = layers.Task.ID
	}
	state, err := a.loadTaskHistory(a.taskID)
	if err != nil {
		return nil, err
	}
	a.restoreConversationLocked(state)
	return a, nil
}

func (a *Agent) historyKey(taskID string) string {
	if taskID == "" {
		return a.conversationID
	}
	return a.conversationID + "/" + taskID
}

func (a *Agent) loadTaskHistory(taskID string) (ConversationState, error) {
	if a.history == nil {
		return ConversationState{}, nil
	}
	state, err := a.history.Load(a.historyKey(taskID))
	if errors.Is(err, ErrHistoryNotFound) && taskID != "" {
		// Read the pre-task-switching history only when it belongs to this task.
		state, err = a.history.Load(a.conversationID)
		if err == nil {
			oldTask := state.MemoryTaskID
			if oldTask == "" {
				oldTask = a.conversationID
			}
			if oldTask != taskID {
				return ConversationState{}, nil
			}
		}
	}
	if errors.Is(err, ErrHistoryNotFound) {
		return ConversationState{}, nil
	}
	if err != nil {
		return ConversationState{}, fmt.Errorf("load conversation history: %w", err)
	}
	return state, nil
}

func (a *Agent) restoreConversationLocked(state ConversationState) {
	a.clearConversationLocked()
	a.previousResponseID = strings.TrimSpace(state.PreviousResponseID)
	a.activeModel = strings.TrimSpace(state.ActiveModel)
	a.messages = cloneMessages(state.Messages)
	if state.Strategy != nil {
		a.strategy = normalizeStrategyConfig(*state.Strategy)
	} else if state.Compression != nil {
		// Histories created by the previous summary-only version migrate to a
		// plain sliding window so new sessions never depend on a summary.
		a.strategy = normalizeStrategyConfig(StrategyConfig{Type: StrategySlidingWindow, KeepLast: state.Compression.KeepLast})
		a.previousResponseID = ""
	}
	a.facts = cloneFacts(state.Facts)
	a.memory = cloneMemoryUsage(state.Memory)
	a.branches = cloneBranches(state.Branches)
	a.activeBranchID = strings.TrimSpace(state.ActiveBranchID)
	a.checkpoint = cloneCheckpoint(state.Checkpoint)
	if state.Summary != nil {
		a.summary = normalizeSummary(*state.Summary, len(a.messages))
	}
	if state.Compression != nil {
		a.compression = normalizeCompressionConfig(*state.Compression)
	}
	if a.strategy.Type == StrategyBranching && a.activeBranchID != "" {
		if branch, ok := a.branches[a.activeBranchID]; ok {
			a.restoreBranchLocked(branch)
		}
	}
	if !a.compression.Enabled && a.summary.MessageCount > 0 {
		a.previousResponseID = ""
	}
}

